from collections import Counter
import heapq


def dependency_solver(preference, name_order):
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        order = names if name_order == "ascending" else names[::-1]
        rows = {name: {row["version"]: row for row in versions}
                for name, versions in packages.items()}
        features = set(data.get("features", []))
        roots = data["roots"]
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        domains = [[-1] + sorted(rows[name]) for name in names]
        best_versions = None
        best_vector = None

        for values in product(*domains):
            selected = dict(zip(names, values))
            installed = {name for name, version in selected.items() if version != -1}
            if any(name not in installed for name in roots):
                continue
            if any(version in blocked.get(name, []) or
                   (name in pins and pins[name] != version)
                   for name, version in selected.items() if version != -1):
                continue

            constraints = {name: [tuple(bounds)] for name, bounds in roots.items()}
            reached = set()
            edges = {}
            pending = list(roots)
            valid = True
            while pending and valid:
                name = pending.pop()
                if name in reached:
                    continue
                reached.add(name)
                version = selected[name]
                if version == -1:
                    valid = False
                    break
                deps = []
                for dep in rows[name][version].get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    other = dep["name"]
                    deps.append(other)
                    constraints.setdefault(other, []).append((dep["min"], dep["max"]))
                    pending.append(other)
                edges[name] = deps

            if not valid or reached != installed:
                continue
            for name, ranges in constraints.items():
                version = selected[name]
                if version == -1 or any(not low <= version <= high
                                        for low, high in ranges):
                    valid = False
                    break
            if not valid:
                continue

            state = {}
            def acyclic(name):
                if state.get(name) == 1:
                    return False
                if state.get(name) == 2:
                    return True
                state[name] = 1
                for other in edges.get(name, []):
                    if not acyclic(other):
                        return False
                state[name] = 2
                return True

            if any(not acyclic(name) for name in reached):
                continue
            vector = tuple(selected[name] for name in order)
            if (best_vector is None or
                    (vector > best_vector if preference == "maximum"
                     else vector < best_vector)):
                best_vector = vector
                best_versions = {name: selected[name] for name in reached}

        if best_versions is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_versions}
    return solve


def component_06(data):
    def rounded(numerator, denominator, mode):
        if mode == "half_up":
            return (numerator * 2 + denominator) // (2 * denominator)
        return numerator // denominator

    chosen = {}
    cutoff = data.get("cutoff", 10**9)
    for position, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (event.get("revision", 0), position)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000, data["rounding"])
        tax = rounded(net * event.get("tax_bp", 0), 10000, data["rounding"])
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def component_07(data):
    jobs = data["jobs"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    k = data["k"]
    best_ids = None
    best_value = None

    for mask in range(1 << len(jobs)):
        if mask.bit_count() != k:
            continue
        chosen = [jobs[i] for i in range(len(jobs)) if mask >> i & 1]
        ids = sorted(job["id"] for job in chosen)
        id_set = set(ids)
        if id_set & blocked or not mandatory <= id_set:
            continue
        counts = Counter(job["group"] for job in chosen)
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        active_ends = []
        valid = True
        for job in sorted(chosen, key=lambda row: (row["start"], row["end"], row["id"])):
            active_ends = [end for end in active_ends if end > job["start"]]
            active_ends.append(job["end"])
            if len(active_ends) > 2:
                valid = False
                break
        if not valid:
            continue
        value = sum(job["value"] for job in chosen)
        if (best_ids is None or value > best_value or
                (value == best_value and ids < best_ids)):
            best_ids, best_value = ids, value

    if best_ids is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def component_08(data):
    required = data.get("required", [])
    bits = {node: 1 << index for index, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial_mask = bits.get(source, 0)
    start_state = (source, initial_mask, data["coupons"])
    dist = {start_state: data["start"]}
    queue = [(data["start"], source, initial_mask, data["coupons"])]
    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if time != dist.get(state):
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}

        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], remaining)]
            if remaining:
                options.append((max(2, edge["duration"] - edge.get("discount", 0)),
                                remaining - 1))
            for duration, left in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                nxt = edge["v"]
                next_mask = mask | bits.get(nxt, 0)
                next_state = (nxt, next_mask, left)
                if arrival < dist.get(next_state, float("inf")):
                    dist[next_state] = arrival
                    heapq.heappush(queue, (arrival, nxt, next_mask, left))
    return {"arrival": None}


